const data = $json.output;
const findings = Array.isArray(data.findings) ? data.findings : [];

const critical = findings.filter(f => f.severity === "Critical").length;
const high = findings.filter(f => f.severity === "High").length;
const medium = findings.filter(f => f.severity === "Medium").length;
const low = findings.filter(f => f.severity === "Low").length;

let score = 100;
score -= critical * 40;
score -= high * 25;
score -= medium * 10;
score -= low * 3;

score = Math.max(0, Math.min(100, score));

let risk = "Informational";

if (critical > 0) risk = "Critical";
else if (high > 0) risk = "High";
else if (medium > 0) risk = "Medium";
else if (low > 0) risk = "Low";

return [{
  json: {
    ...data,
    risk_calculation: {
      critical_findings: critical,
      high_findings: high,
      medium_findings: medium,
      low_findings: low,
      calculated_security_score: score,
      calculated_overall_risk: risk
    }
  }
}];
